// Deal lines arrive as decimal strings from the API, so every number is cast before use.
// A deal line carries no tax rate, so the rate from "Billing Rules" is applied to all of them.
const deal = $('Get Deal').first().json;
const rules = $('Billing Rules').first().json;
const num = (v) => (v === null || v === undefined || v === '' ? 0 : Number(v));

const taxRate = num(rules.taxRatePercent);
const termDays = num(rules.paymentTermDays);
const depositPercent = num(rules.depositPercent);
const depositFrom = num(rules.depositFromNetValue);

const dealLines = Array.isArray(deal.lines) ? deal.lines : [];
const netFromLines = dealLines.reduce((s, l) => s + num(l.quantity) * num(l.pricePerUnit), 0);
const net = dealLines.length ? netFromLines : num(deal.dealValue);
const isDeposit = depositFrom > 0 && net >= depositFrom;

const line = (i, shortText, quantity, unit, priceBase, longText) => ({
  positionType: 'NORMAL',
  position: String(i),
  shortText: shortText || 'Position',
  longText: longText || '',
  quantity: quantity || 1,
  unit: unit || 'Stk',
  priceBase: priceBase,
  taxRate,
});

let invoiceLines;
if (isDeposit) {
  invoiceLines = [
    line(1, `Deposit ${depositPercent} % - ${deal.title}`, 1, 'Stk', (net * depositPercent) / 100),
  ];
} else if (dealLines.length) {
  invoiceLines = dealLines.map((l, i) =>
    line(i + 1, l.assetName, num(l.quantity), l.unit, num(l.pricePerUnit), l.assetDescription),
  );
} else {
  invoiceLines = [line(1, deal.title, 1, 'Stk', net)];
}

const billed = invoiceLines.reduce((s, l) => s + l.quantity * l.priceBase, 0);
const dueDate = new Date(Date.now() + termDays * 86400000).toISOString();

return [
  {
    json: {
      isDeposit,
      invoice: {
        title: isDeposit ? `Deposit invoice - ${deal.title}` : `Invoice - ${deal.title}`,
        invoicingDate: new Date().toISOString(),
        netGross: 'net',
      },
      customer: { clientType: 'PERSON', clientId: deal.contacts[0].id },
      invoiceLines,
      // dueDate and skonto are both required on paymentTerms, and skonto needs days and percent.
      paymentTerms: { dueDate, skonto: { days: 0, percent: 0 } },
      summary: {
        dealId: deal.id,
        dealTitle: deal.title,
        positions: invoiceLines.length,
        netBilled: billed,
        currency: deal.currency || 'EUR',
      },
    },
  },
];
